function countingSort(a) {
  if (a.length === 0) return a;
  const max = Math.max(...a);
  const count = new Array(max + 1).fill(0);
  for (const x of a) count[x]++;
  const result = [];
  for (let v = 0; v <= max; v++) {
    while (count[v]-- > 0) result.push(v);
  }
  return result;
}

