def counting_sort(a):
    if not a:
        return a
    lo, hi = min(a), max(a)
    count = [0] * (hi - lo + 1)
    for x in a:
        count[x - lo] += 1
    result = []
    for i, c in enumerate(count):
        result.extend([i + lo] * c)
    return result

print(counting_sort([4, 2, 2, 8, 3, 3, 1]))
